using DriveOS.Application.Abstractions.Messaging;using DriveOS.Application.Abstractions.Time;using DriveOS.Modules.Workforce.Application.Persistence;using DriveOS.Modules.Workforce.Domain.Employees;using DriveOS.Modules.Workforce.Domain.ProfessionalRestrictions;using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.Workforce.Application.ProfessionalRestrictions;
public sealed class CreateProfessionalRestrictionCommandHandler(IProfessionalRestrictionRepository repo,IEmployeeRepository employees,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<CreateProfessionalRestrictionCommand,DriveOS.SharedKernel.Identifiers.ProfessionalRestrictionId>{public async Task<Result<DriveOS.SharedKernel.Identifiers.ProfessionalRestrictionId>> Handle(CreateProfessionalRestrictionCommand c,CancellationToken ct){var e=await employees.GetByIdAsync(c.OrganizationId,c.EmployeeId,ct);if(e is null)return Result.Failure<DriveOS.SharedKernel.Identifiers.ProfessionalRestrictionId>(EmployeeErrors.NotFound);if(e.Status==EmploymentStatus.Ended)return Result.Failure<DriveOS.SharedKernel.Identifiers.ProfessionalRestrictionId>(EmployeeErrors.InvalidLifecycleTransition);if(await repo.HasOverlapAsync(c.OrganizationId,c.EmployeeId,c.Activity,c.StartDate,c.EndDate,c.CountryCode,c.LicenseCategoryCode,c.BranchId,null,ct))return Result.Failure<DriveOS.SharedKernel.Identifiers.ProfessionalRestrictionId>(ProfessionalRestrictionErrors.Overlap);var r=ProfessionalRestriction.Create(c.Id,c.OrganizationId,c.EmployeeId,c.Activity,c.Source,c.StartDate,c.EndDate,c.Reason,c.CountryCode,c.LicenseCategoryCode,c.BranchId,c.SupportingDocumentReferenceId,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return Result.Failure<DriveOS.SharedKernel.Identifiers.ProfessionalRestrictionId>(r.Error);repo.Add(r.Value);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
public sealed class UpdateProfessionalRestrictionCommandHandler(IProfessionalRestrictionRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<UpdateProfessionalRestrictionCommand>{public async Task<Result> Handle(UpdateProfessionalRestrictionCommand c,CancellationToken ct){var x=await repo.GetAsync(c.OrganizationId,c.Id,true,ct);if(x is null)return Result.Failure(ProfessionalRestrictionErrors.NotFound);if(await repo.HasOverlapAsync(c.OrganizationId,x.EmployeeId,x.Activity,c.StartDate,c.EndDate,c.CountryCode,c.LicenseCategoryCode,c.BranchId,c.Id,ct))return Result.Failure(ProfessionalRestrictionErrors.Overlap);var r=x.UpdatePlan(c.StartDate,c.EndDate,c.Reason,c.CountryCode,c.LicenseCategoryCode,c.BranchId,c.SupportingDocumentReferenceId,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class ActivateProfessionalRestrictionCommandHandler(IProfessionalRestrictionRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<ActivateProfessionalRestrictionCommand>{public async Task<Result> Handle(ActivateProfessionalRestrictionCommand c,CancellationToken ct){var x=await repo.GetAsync(c.OrganizationId,c.Id,true,ct);if(x is null)return Result.Failure(ProfessionalRestrictionErrors.NotFound);var r=x.Activate(clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class LiftProfessionalRestrictionCommandHandler(IProfessionalRestrictionRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<LiftProfessionalRestrictionCommand>{public async Task<Result> Handle(LiftProfessionalRestrictionCommand c,CancellationToken ct){var x=await repo.GetAsync(c.OrganizationId,c.Id,true,ct);if(x is null)return Result.Failure(ProfessionalRestrictionErrors.NotFound);var r=x.Lift(c.Reason,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class CancelProfessionalRestrictionCommandHandler(IProfessionalRestrictionRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<CancelProfessionalRestrictionCommand>{public async Task<Result> Handle(CancelProfessionalRestrictionCommand c,CancellationToken ct){var x=await repo.GetAsync(c.OrganizationId,c.Id,true,ct);if(x is null)return Result.Failure(ProfessionalRestrictionErrors.NotFound);var r=x.Cancel(c.Reason,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class GetProfessionalRestrictionQueryHandler(IProfessionalRestrictionRepository repo):IQueryHandler<GetProfessionalRestrictionQuery,ProfessionalRestrictionResponse>{public async Task<Result<ProfessionalRestrictionResponse>> Handle(GetProfessionalRestrictionQuery q,CancellationToken ct){var x=await repo.GetAsync(q.OrganizationId,q.Id,false,ct);return x is null?Result.Failure<ProfessionalRestrictionResponse>(ProfessionalRestrictionErrors.NotFound):Result.Success(Map(x));}internal static ProfessionalRestrictionResponse Map(ProfessionalRestriction x)=>new(x.Id.Value,x.EmployeeId.Value,x.Activity.ToString(),x.Source.ToString(),x.StartDate,x.EndDate,x.Reason,x.CountryCode,x.LicenseCategoryCode,x.BranchId?.Value,x.SupportingDocumentReferenceId,x.Status.ToString(),x.ActivatedAtUtc,x.LiftedAtUtc,x.LiftReason,x.CancellationReason);}
public sealed class GetProfessionalRestrictionsQueryHandler(IProfessionalRestrictionRepository repo):IQueryHandler<GetProfessionalRestrictionsQuery,IReadOnlyList<ProfessionalRestrictionResponse>>{public async Task<Result<IReadOnlyList<ProfessionalRestrictionResponse>>> Handle(GetProfessionalRestrictionsQuery q,CancellationToken ct)=>Result.Success<IReadOnlyList<ProfessionalRestrictionResponse>>((await repo.ListAsync(q.OrganizationId,q.EmployeeId,q.Status,q.Activity,ct)).Select(GetProfessionalRestrictionQueryHandler.Map).ToArray());}
